package org.opensourcepingpong.competition;

import jakarta.validation.Valid;
import java.time.Instant;
import java.sql.Timestamp;
import java.sql.Types;
import java.util.*;
import org.opensourcepingpong.auth.AuthPrincipal;
import org.opensourcepingpong.common.api.*;
import org.opensourcepingpong.organization.*;
import org.opensourcepingpong.rating.RatingSettlementService;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1")
public class CompetitionController {
  private final JdbcTemplate jdbc; private final AuthorizationService auth; private final ScheduleService schedules; private final RatingSettlementService ratings;
  public CompetitionController(JdbcTemplate jdbc, AuthorizationService auth, ScheduleService schedules, RatingSettlementService ratings){this.jdbc=jdbc;this.auth=auth;this.schedules=schedules;this.ratings=ratings;}
  @GetMapping("/competitions") ApiResponse<?> list(){return ApiResponse.ok(jdbc.queryForList("select c.id,c.title,c.competition_type,c.format,c.status,c.location,c.registration_end,c.start_time,s.code sport_code,s.name sport_name from competitions c join sports s on s.id=c.sport_id order by c.created_at desc"));}
  @GetMapping("/competitions/{id}") ApiResponse<?> detail(@PathVariable UUID id){var rows=jdbc.queryForList("select c.*,s.code sport_code,s.name sport_name from competitions c join sports s on s.id=c.sport_id where c.id=?",id);if(rows.isEmpty())throw missing();return ApiResponse.ok(rows.getFirst());}
  @PostMapping("/admin/competitions") ApiResponse<Map<String,UUID>> create(@AuthenticationPrincipal AuthPrincipal p,@Valid @RequestBody Create r){
    auth.require(p.userId(),Permission.COMPETITION_CREATE); if(r.type()==null||r.format()==null||!(r.bestOf()==3||r.bestOf()==5||r.bestOf()==7))throw new BusinessException(HttpStatus.UNPROCESSABLE_ENTITY,"VALIDATION_ERROR","invalid competition parameters");
    UUID sportId=activeSport(r.sportCode());
    ensureRatingSport(r.type(), r.sportCode());
    UUID id=UUID.randomUUID();
    jdbc.update("insert into competitions(id,title,description,competition_type,event_type,sport_id,format,status,registration_scope,registration_requires_review,max_participants,best_of,location,registration_start,registration_end,start_time,creator_user_id) values(?,?,?,?,?,?,?,'DRAFT',?,?,?,?,?,?,?,?,?)", ps->{ps.setObject(1,id);ps.setString(2,r.title());if(r.description()==null)ps.setNull(3,Types.VARCHAR);else ps.setString(3,r.description());ps.setString(4,r.type().name());ps.setString(5,"SINGLES");ps.setObject(6,sportId);ps.setString(7,r.format().name());ps.setString(8,r.scope());ps.setBoolean(9,r.review());ps.setInt(10,r.maxParticipants());ps.setInt(11,r.bestOf());ps.setString(12,r.location());ps.setTimestamp(13,Timestamp.from(r.registrationStart()));ps.setTimestamp(14,Timestamp.from(r.registrationEnd()));ps.setTimestamp(15,Timestamp.from(r.startTime()));ps.setObject(16,p.userId());});
    return ApiResponse.ok(Map.of("id",id));
  }
  @PostMapping("/admin/competitions/{id}/publish") ApiResponse<Void> publish(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id){transition(p.userId(),id,"publish");return ApiResponse.ok(null);}
  @PostMapping("/admin/competitions/{id}/close-registration") ApiResponse<Void> close(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id){transition(p.userId(),id,"close");return ApiResponse.ok(null);}
  @PutMapping("/admin/competitions/{id}") ApiResponse<Void> update(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id,@Valid @RequestBody Create r){auth.require(p.userId(),Permission.COMPETITION_MANAGE);var rows=jdbc.queryForList("select status from competitions where id=?",id);if(rows.isEmpty())throw missing();String status=(String)rows.getFirst().get("status");if(!Set.of("DRAFT","REGISTRATION").contains(status))throw new BusinessException(HttpStatus.CONFLICT,"COMPETITION_INVALID_STATE","competition cannot be edited");UUID sportId=activeSport(r.sportCode());ensureRatingSport(r.type(),r.sportCode());jdbc.update("update competitions set title=?,description=?,competition_type=?,sport_id=?,format=?,registration_scope=?,registration_requires_review=?,max_participants=?,best_of=?,location=?,registration_start=?,registration_end=?,start_time=?,updated_at=?,version=version+1 where id=?",r.title(),r.description(),r.type().name(),sportId,r.format().name(),r.scope(),r.review(),r.maxParticipants(),r.bestOf(),r.location(),Timestamp.from(r.registrationStart()),Timestamp.from(r.registrationEnd()),Timestamp.from(r.startTime()),Timestamp.from(Instant.now()),id);return ApiResponse.ok(null);}
  @PostMapping("/admin/competitions/{id}/arrange") ApiResponse<Void> arrange(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id,@RequestBody(required=false) Map<String,Long> body){schedules.arrange(p.userId(),id,body==null?System.currentTimeMillis():body.getOrDefault("seed",System.currentTimeMillis()));return ApiResponse.ok(null);}
  @PostMapping("/admin/competitions/{id}/start") ApiResponse<Void> start(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id){schedules.start(p.userId(),id);return ApiResponse.ok(null);}
  @PostMapping("/admin/competitions/{id}/enter-result-confirming") ApiResponse<Void> confirming(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id){schedules.confirming(p.userId(),id);return ApiResponse.ok(null);}
  @PostMapping("/admin/competitions/{id}/finalize") ApiResponse<Void> finalizeCompetition(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id){ratings.finalizeCompetition(p.userId(),id);return ApiResponse.ok(null);}
  @PostMapping("/admin/competitions/{id}/cancel") ApiResponse<Void> cancel(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id){transition(p.userId(),id,"cancel");return ApiResponse.ok(null);}
  @GetMapping("/competitions/{id}/schedule") ApiResponse<?> schedule(@PathVariable UUID id){return ApiResponse.ok(jdbc.queryForList("select id,round_number,match_number,group_id,status,player_a_user_id,player_b_user_id,winner_user_id,result_type,player_a_games,player_b_games,best_of,version from matches where competition_id=? order by round_number,match_number",id));}
  @GetMapping("/competitions/{id}/bracket") ApiResponse<?> bracket(@PathVariable UUID id){return ApiResponse.ok(jdbc.queryForList("select id,round_number,match_number,status,player_a_user_id,player_b_user_id,winner_user_id,next_match_id,winner_to_slot from matches where competition_id=? and group_id is null order by round_number,match_number",id));}
  @GetMapping("/competitions/{id}/groups") ApiResponse<?> groups(@PathVariable UUID id){return ApiResponse.ok(jdbc.queryForList("select g.id,g.name,g.group_order,gm.user_id,gm.position from competition_groups g join competition_stages s on s.id=g.stage_id left join competition_group_members gm on gm.group_id=g.id where s.competition_id=? order by g.group_order,gm.position",id));}
  @PostMapping("/competitions/{id}/entries") ApiResponse<Void> enter(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id){var c=jdbc.queryForList("select status,max_participants,registration_requires_review from competitions where id=?",id);if(c.isEmpty())throw missing();if(!"REGISTRATION".equals(c.getFirst().get("status")))throw new BusinessException(HttpStatus.CONFLICT,"COMPETITION_REGISTRATION_CLOSED","registration is closed");int count=jdbc.queryForObject("select count(*) from competition_entries where competition_id=? and status in ('PENDING','APPROVED')",Integer.class,id);if(count>=((Number)c.getFirst().get("max_participants")).intValue())throw new BusinessException(HttpStatus.CONFLICT,"COMPETITION_FULL","competition is full");try{boolean review=(Boolean)c.getFirst().get("registration_requires_review");jdbc.update("insert into competition_entries(id,competition_id,user_id,status,registered_at)values(?,?,?,?,?)",ps->{ps.setObject(1,UUID.randomUUID());ps.setObject(2,id);ps.setObject(3,p.userId());ps.setString(4,review?"PENDING":"APPROVED");ps.setTimestamp(5,Timestamp.from(Instant.now()));});}catch(DuplicateKeyException e){throw new BusinessException(HttpStatus.CONFLICT,"COMPETITION_ALREADY_REGISTERED","already registered");}return ApiResponse.ok(null);}
  @DeleteMapping("/competitions/{id}/entries/me") ApiResponse<Void> leave(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id){var c=jdbc.queryForList("select status from competitions where id=?",id);if(c.isEmpty())throw missing();if(!"REGISTRATION".equals(c.getFirst().get("status")))throw new BusinessException(HttpStatus.CONFLICT,"COMPETITION_REGISTRATION_CLOSED","registration is closed");int changed=jdbc.update("delete from competition_entries where competition_id=? and user_id=? and status in ('PENDING','APPROVED')",id,p.userId());if(changed!=1)throw new BusinessException(HttpStatus.NOT_FOUND,"ENTRY_NOT_FOUND","entry not found");return ApiResponse.ok(null);}
  @GetMapping("/admin/competitions/{id}/entries") ApiResponse<?> entries(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID id){auth.require(p.userId(),Permission.COMPETITION_MANAGE);return ApiResponse.ok(jdbc.queryForList("select e.id,e.user_id,e.status,e.seed_number,e.registered_at,e.approved_at,p.nickname,p.real_name from competition_entries e left join user_profiles p on p.user_id=e.user_id where e.competition_id=? order by e.registered_at",id));}
  @PostMapping("/admin/competition-entries/{entryId}/approve") ApiResponse<Void> approveEntry(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID entryId){reviewEntry(p.userId(),entryId,true);return ApiResponse.ok(null);}
  @PostMapping("/admin/competition-entries/{entryId}/reject") ApiResponse<Void> rejectEntry(@AuthenticationPrincipal AuthPrincipal p,@PathVariable UUID entryId){reviewEntry(p.userId(),entryId,false);return ApiResponse.ok(null);}
  private void transition(UUID user,UUID id,String action){auth.require(user,Permission.COMPETITION_MANAGE);var rows=jdbc.queryForList("select status from competitions where id=?",id);if(rows.isEmpty())throw missing();CompetitionStatus to=CompetitionStateMachine.next(CompetitionStatus.valueOf((String)rows.getFirst().get("status")),action);jdbc.update("update competitions set status=? where id=?",to.name(),id);}
  private UUID activeSport(String code){String normalized=code==null||code.isBlank()?"PING_PONG":code.trim().toUpperCase(Locale.ROOT);var rows=jdbc.queryForList("select id from sports where code=? and active=true",normalized);if(rows.isEmpty())throw new BusinessException(HttpStatus.UNPROCESSABLE_ENTITY,"SPORT_NOT_FOUND","运动类型不存在或已停用");return (UUID)rows.getFirst().get("id");}
  private void ensureRatingSport(CompetitionType type,String code){String normalized=code==null||code.isBlank()?"PING_PONG":code.trim().toUpperCase(Locale.ROOT);if(type==CompetitionType.RATED&&!normalized.equals("PING_PONG"))throw new BusinessException(HttpStatus.UNPROCESSABLE_ENTITY,"SPORT_RATING_UNSUPPORTED","其他运动类型暂不支持积分赛事");}
  private void reviewEntry(UUID user,UUID entryId,boolean approve){auth.require(user,Permission.COMPETITION_MANAGE);var rows=jdbc.queryForList("select e.status,c.status competition_status from competition_entries e join competitions c on c.id=e.competition_id where e.id=?",entryId);if(rows.isEmpty())throw new BusinessException(HttpStatus.NOT_FOUND,"ENTRY_NOT_FOUND","entry not found");if(!"REGISTRATION".equals(rows.getFirst().get("competition_status"))||!"PENDING".equals(rows.getFirst().get("status")))throw new BusinessException(HttpStatus.CONFLICT,"COMPETITION_INVALID_STATE","entry cannot be reviewed");Timestamp now=Timestamp.from(Instant.now());jdbc.update("update competition_entries set status=?,approved_at=?,updated_at=? where id=?",approve?"APPROVED":"REJECTED",approve?now:null,now,entryId);}
  private static BusinessException missing(){return new BusinessException(HttpStatus.NOT_FOUND,"COMPETITION_NOT_FOUND","competition not found");}
  public record Create(@jakarta.validation.constraints.NotBlank @jakarta.validation.constraints.Size(max=120) String title,String description,CompetitionType type,CompetitionFormat format,@jakarta.validation.constraints.NotBlank String scope,boolean review,@jakarta.validation.constraints.Min(2) int maxParticipants,int bestOf,@jakarta.validation.constraints.NotBlank String location,Instant registrationStart,Instant registrationEnd,Instant startTime,String sportCode){}
}
